#!/usr/bin/env python3
"""A script phase that builds and runs a local Swift package's tool with `swift run`, for a
self-written app (home-assistant's `Tools/build_tool`, which runs SwiftGen and SwiftLint from
its `BuildTools` package).

envelope_experiments.py's objectVersion-77 app, its script phase changed to run
`env -u SDKROOT swift run --package-path "$SRCROOT/Tool" Tool <output>`, the output declared in the app's
resources; the package's executable writes a line into it.

Usage:
  script_swiftpm_experiments.py <out>                  on a Mac: xcodebuild (DEVELOPER_DIR)
  script_swiftpm_experiments.py <out> --nomac <nomac> [nomac build options...]

<out>/<tool>.log keeps the build's output; <out>/<tool>.json lists the exit status and the
contents of the tool's output in the app.
"""

import json
import os
import shutil
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import envelope_experiments as envelope  # noqa: E402

PACKAGE = """// swift-tools-version: 5.9
import PackageDescription

let package = Package(name: "Tool", targets: [.executableTarget(name: "Tool")])
"""
TOOL = """import Foundation

try "generated by the package's tool\\n".write(toFile: CommandLine.arguments[1], atomically: true, encoding: .utf8)
"""
# Without the build's SDKROOT (the iOS SDK), as home-assistant's phase runs it, so that SwiftPM
# builds for the build machine.
SCRIPT = 'env -u SDKROOT swift run --package-path "$SRCROOT/Tool" Tool "$SCRIPT_OUTPUT_FILE_0"\n'


def project():
    def edit(p, files):
        phase = p.objects[p.ids("app/script")]
        phase.update(shellScript=SCRIPT, inputPaths=[], outputPaths=["$(TARGET_BUILD_DIR)/$(UNLOCALIZED_RESOURCES_FOLDER_PATH)/generated.txt"])
        files["Tool/Package.swift"] = PACKAGE
        files["Tool/Sources/Tool/main.swift"] = TOOL
        sources = p.objects[p.ids("app/sources")]
        sources["files"] = [build for build in sources["files"] if build != p.ids("app/model/build")]
    return envelope.era_project(77, edit=edit)


def main():
    out = Path(sys.argv[1]).resolve()
    nomac = sys.argv[sys.argv.index("--nomac") + 1] if "--nomac" in sys.argv else None
    extra = sys.argv[sys.argv.index("--nomac") + 2:] if nomac else []
    tool = "nomac" if nomac else "xcode"
    source = out / f"src-{tool}"
    shutil.rmtree(source, ignore_errors=True)
    for path, text in project().items():
        (source / path).parent.mkdir(parents=True, exist_ok=True)
        (source / path).write_text(text)
    derived = out / f"dd-{tool}"
    shutil.rmtree(derived, ignore_errors=True)
    command = ([nomac, "build"] if nomac else ["xcodebuild"]) + [
        "-project", "P.xcodeproj", "-scheme", "App", "-configuration", "Debug", "-destination", "generic/platform=iOS",
        "-derivedDataPath", str(derived), "CODE_SIGNING_ALLOWED=NO", "ASSETCATALOG_COMPILER_APPICON_NAME=", *extra, "build"]
    completed = subprocess.run(command, cwd=source, capture_output=True, text=True, env=os.environ)
    (out / f"{tool}.log").write_text(completed.stdout + completed.stderr)
    output = derived / "Build/Products/Debug-iphoneos/App.app/generated.txt"
    results = {"exitStatus": completed.returncode, "output": output.read_text() if output.exists() else None}
    (out / f"{tool}.json").write_text(json.dumps(results, indent=2) + "\n")
    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()
